    internal static class ProfileResetMemoryCutoverV1
    {
        // Cleanup has crossed C2's accepted terminal boundary. Its exception
        // must dominate any prior outcome as ReloadRequired, never be
        // reclassified as a filesystem/manual-repair disk observation.
        private sealed class ResetCandidateCleanupFailureV1 : Exception { internal ResetCandidateCleanupFailureV1(Exception inner) : base("Reset staged-candidate cleanup failed.",inner) { } }
        internal static ProfileResetMemoryResultV1 FinalizeReset(string root,ProfileResetDiskPreparedProofV1 proof,DesktopProfileLaunchAdapterV1 owner,InputRouter router){return FinalizeReset(root,proof,owner,router,ProfileResetMemoryCutoverNoOpControlV1.Instance);}
        // REQ-M5D7QC2R-002/004. This is deliberately a separate private entry:
        // only the adapter's same-call Resume result can supply its proof.
        internal static ProfileResetMemoryResultV1 FinalizeRestartRecovery(string root,ProfileResetDiskResultV1 resumed,DesktopProfileLaunchAdapterV1 owner,InputRouter router,IProfileResetMemoryCutoverControlV1 control)
        {
            if(root==null||owner==null||router==null||control==null)throw new ArgumentNullException();
            resumed.Validate(); if(resumed.Outcome!=ProfileResetDiskOutcomeV1.DiskPrepared)throw new InvalidOperationException("Only the adapter's registered DiskPrepared Resume result may enter recovery.");
            if(!owner.IsExactRestartRecovery(router,root,resumed))throw new InvalidOperationException("Restart recovery entry is not an exact private cohort.");
            if(!owner.TryBeginRestartRecoveryExecution(router,root,resumed))throw new InvalidOperationException("Restart recovery execution was already consumed.");
            string normalized;
            try { normalized=ProfileResetDiskTransactionV1.ValidateMemoryResetRootBeforeLease(root); }
            catch(IOException) { owner.LatchResetCutoverFailure(); return new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.ManualRepairRequired); }
            catch(UnauthorizedAccessException) { owner.LatchResetCutoverFailure(); return new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.ManualRepairRequired); }
            catch(ArgumentException) { owner.LatchResetCutoverFailure(); return new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.ManualRepairRequired); }
            ProfileRootOperationLockV1 lease;
            try { lease=ProfileRootOperationLockV1.Acquire(normalized); }
            catch(ProfileRootOperationBlockedExceptionV1 e) when(e.Outcome==ProfileRootOperationOutcomeV1.Busy) { return new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.Busy); }
            catch { owner.LatchResetCutoverFailure(); return new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.ManualRepairRequired); }
            using(lease)
            {
                GameInputActions staged=null; ProfileResetMemoryResultV1 result=null;
                try
                {
                    var authority=ProfileResetDiskTransactionV1.ReauthenticatePreparedUnderHeldRoot(lease,normalized,resumed.PreparedProof,control);
                    control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeStaging); var doc=ProfileRecoveryPlannerV1.PlanDefaultBootstrap().ResultDocument; doc.Validate(); if(!Bytes(doc.CanonicalFileBytes,authority.CopyTargetBytes()))throw new InvalidOperationException();
                    staged=new GameInputActions(); owner.RegisterRestartRecoveryCandidate(staged,control); router.ValidateAllMapsDisabled(staged); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterCandidateCreate); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeBindingApply); var binding=ProfileBindingOverrideApplyAdapterV1.Apply(doc.Snapshot.Input,staged); binding.Validate(); if(binding.Outcome!=ProfileBindingOverrideApplyOutcomeV1.DefaultsReady||binding.Failure!=ProfileBindingOverrideApplyFailureV1.None||binding.CandidateDisposition!=ProfileBindingOverrideCandidateDispositionV1.Retain||!doc.Snapshot.Input.BindingOverrides.IsEmpty)throw new InvalidOperationException(); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterBindingApply);
                    control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeTerminalGate); authority.ValidateForHeldLease(lease,normalized); owner.AdoptResetCandidateForTerminal(staged,control); staged=null; var cap=owner.EnterRestartRecoveryTerminal(normalized,authority,control); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterTerminalGate); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeTransfer); router.TransferRestartRecoveryActions(cap); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterTransfer); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeCell); owner.PublishCurrentSessionProfile(cap,doc,binding); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterCell);
                    control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforePair); if(!owner.ValidateResetPair(cap))throw new InvalidOperationException(); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterPair); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeDelete); ProfileResetDiskTransactionV1.RemoveAuthenticatedBarrierUnderHeldRoot(lease,authority,control); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterDelete); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeFinalProbe); var final=ProfileResetDiskTransactionV1.CaptureFinalDiskProofUnderHeldRoot(lease,authority,control); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.AfterFinalProbe);
                    if(!owner.ValidateResetPair(cap))throw new InvalidOperationException(); control.Checkpoint(ProfileResetMemoryCutoverCheckpointV1.BeforeReceiptStage); var receipt=ProfileResetMemoryReceiptV1.CreateFinal(final,owner.CurrentResetSession,binding,cap); var bootstrap=RestartBootstrapResultV1.Create(RestartBootstrapOutcomeV1.Completed,receipt); result=new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.Completed,receipt,bootstrap); owner.PublishResetReceipt(receipt,cap);
                }
