                catch { owner.LatchResetCutoverFailure(); result=new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.ReloadRequired); }
                finally { if(staged!=null) { try { owner.DisposeUntransferredResetCandidate(staged,control); } catch { owner.LatchResetCutoverFailure(); result=new ProfileResetMemoryResultV1(ProfileResetMemoryOutcomeV1.ReloadRequired); } } }
                return result;
